using MediLabX.Native.Models;
using MediLabX.Native.Services;
using Microsoft.Win32;
using System.Windows;
using System.Windows.Controls;
namespace MediLabX.Native;
public partial class MainWindow {
 private FrameworkElement Admin(){var tabs=new TabControl{Margin=new Thickness(0,0,0,20)};foreach(var (name,content) in new[]{("Employees",EmployeePage()),("Experience Certificates",ExperiencePage()),("Leave",LeavePage()),("Salary Slips",PayrollPage()),("Users & Roles",AccountsPage())})tabs.Items.Add(new TabItem{Header=name,Content=new ScrollViewer{Content=content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto}});return tabs;}
 private FrameworkElement EmployeePage(){var root=Column();var p=Column();var name=Field(p,"Employee name");var position=Field(p,"Position (Lab Technologist, Receptionist, etc.)");var dept=Field(p,"Department");var joined=Field(p,"Joining date",Today);var left=Field(p,"Last working date (optional)");var salary=Field(p,"Monthly salary (Rs)");p.Children.Add(Action("Save employee",()=>{if(string.IsNullOrWhiteSpace(name.Text))return;var e=new Employee{Name=name.Text,Position=position.Text,Department=dept.Text,Joined=joined.Text,Left=left.Text,MonthlySalary=Dec(salary.Text)};SaveAndRefresh("employees",e.Id,e,"Employee saved.");},true));root.Children.Add(Card(p,"Employee directory"));root.Children.Add(Card(GridView(store.All<Employee>("employees"),320),"Saved employees"));return root;}
 private FrameworkElement ExperiencePage(){var root=Column();var p=Column();var workers=store.All<Employee>("employees");var choice=Select(p,"Employee",workers.Select(x=>x.Name));var text=Field(p,"Editable experience text","During their employment, the employee performed assigned professional responsibilities diligently.",3000);text.AcceptsReturn=true;text.TextWrapping=TextWrapping.Wrap;text.Height=110;var withHeading=Check(p,"Print digital heading on blank A4 (uncheck for official printed letterhead)");p.Children.Add(Text("Preprinted letterhead protection: 6.5 cm header and 5 cm footer are reserved by default.",11));p.Children.Add(Action("Preview / Print certificate",()=>{var e=workers.FirstOrDefault(x=>x.Name==choice.SelectedItem?.ToString());if(e is not null)printer.Experience(e,text.Text,store.Settings,withHeading.IsChecked==true);},true));root.Children.Add(Card(p,"Experience certificate"));return root;}
 private FrameworkElement LeavePage(){var root=Column();var p=Column();var employees=store.All<Employee>("employees");var employee=Select(p,"Employee",employees.Select(x=>x.Name));var from=Field(p,"From",Today);var to=Field(p,"To",Today);var reason=Field(p,"Reason");p.Children.Add(Action("Submit leave request",()=>{var e=employees.FirstOrDefault(x=>x.Name==employee.SelectedItem?.ToString());if(e is null)return;var leave=new LeaveRecord{EmployeeId=e.Id,Start=from.Text,End=to.Text,Reason=reason.Text};SaveAndRefresh("leaves",leave.Id,leave,"Leave request recorded.");},true));root.Children.Add(Card(p,"Leave management"));var leaves=store.All<LeaveRecord>("leaves");var grid=GridView(leaves.Select(x=>new{Employee=employees.FirstOrDefault(e=>e.Id==x.EmployeeId)?.Name,x.Start,x.End,x.Reason,x.Status,Record=x}).ToList(),320);root.Children.Add(Card(grid,"Leave history"));LeaveRecord? selected()=>grid.SelectedItem is null?null:(LeaveRecord?)grid.SelectedItem.GetType().GetProperty("Record")?.GetValue(grid.SelectedItem);var bar=Row();bar.Children.Add(Action("Approve",()=>{var x=selected();if(x is null)return;x.Status="Approved";store.Put("leaves",x.Id,x);OpenPage(page);}));bar.Children.Add(Action("Reject",()=>{var x=selected();if(x is null)return;x.Status="Rejected";store.Put("leaves",x.Id,x);OpenPage(page);}));bar.Children.Add(Action("Print",()=>{var x=selected();if(x is null)return;var emp=employees.FirstOrDefault(e=>e.Id==x.EmployeeId);if(emp is not null)printer.Leave(emp,x,store.Settings,false);}));root.Children.Add(Card(bar));return root;}
 private FrameworkElement PayrollPage(){var root=Column();var p=Column();var employees=store.All<Employee>("employees");var pick=Select(p,"Employee",employees.Select(x=>x.Name));var month=Field(p,"Salary month (YYYY-MM)",DateTime.Today.ToString("yyyy-MM"));var gross=Field(p,"Gross salary (Rs)","0");var deductions=Field(p,"Deductions (Rs)","0");var heading=Check(p,"With digital heading (uncheck for printed letterhead)");p.Children.Add(Action("Save and print salary slip",()=>{var e=employees.FirstOrDefault(x=>x.Name==pick.SelectedItem?.ToString());if(e is null)return;var slip=new SalarySlip{EmployeeId=e.Id,Month=month.Text,Gross=Dec(gross.Text),Deductions=Dec(deductions.Text)};if(slip.Net<0){Info("Deductions cannot exceed gross salary.");return;}store.Put("salaries",slip.Id,slip);printer.Salary(e,slip,store.Settings,heading.IsChecked==true);OpenPage(page);},true));root.Children.Add(Card(p,"Salary slips"));root.Children.Add(Card(GridView(store.All<SalarySlip>("salaries").Select(x=>new{x.Month,Employee=employees.FirstOrDefault(e=>e.Id==x.EmployeeId)?.Name,x.Gross,x.Deductions,x.Net}).ToList(),300),"Payroll history"));return root;}
 private FrameworkElement AccountsPage(){var root=Column();var p=Column();var name=Field(p,"Display name");var user=Field(p,"Username");var pass=Field(p,"Temporary password (min 10 characters)");var role=Select(p,"Role",new[]{"Reception","Admin"});var perms=Field(p,"Page permissions (comma separated)","Reception, Patients & Receipts, Radiology Reports");p.Children.Add(Action("Create account",()=>{if(user.Text.Length<2||pass.Text.Length<10){Info("Username and password (at least 10 characters) required.");return;}if(store.All<LocalUser>("users").Any(x=>x.UserName.Equals(user.Text,StringComparison.OrdinalIgnoreCase))){Info("Username already exists.");return;}var u=new LocalUser{UserName=user.Text.Trim(),DisplayName=name.Text.Trim(),Role=role.SelectedItem?.ToString()??"Reception",PasswordHash=Security.Hash(pass.Text),Permissions=perms.Text.Split(',',StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries).ToList()};SaveAndRefresh("users",u.Id,u,"User created.");},true));root.Children.Add(Card(p,"Role-based accounts"));root.Children.Add(Card(GridView(store.All<LocalUser>("users").Select(u=>new{u.UserName,u.DisplayName,u.Role,Permissions=string.Join(", ",u.Permissions)}).ToList(),270),"Saved users"));return root;}
 private FrameworkElement Settings(){var root=Column();var tabs=new TabControl();tabs.Items.Add(new TabItem{Header="Appearance",Content=AppearanceSettings()});tabs.Items.Add(new TabItem{Header="Doctors",Content=DoctorsSettings()});tabs.Items.Add(new TabItem{Header="Print Layout",Content=PrintSettings()});tabs.Items.Add(new TabItem{Header="Now Brief",Content=BriefSettings()});tabs.Items.Add(new TabItem{Header="Data & Updates",Content=DataSettings()});root.Children.Add(tabs);return root;}
 private FrameworkElement AppearanceSettings(){var p=Column();p.Children.Add(Text("One consistent modern desktop theme",16,true));var dark=Check(p,"Enable Dark Mode",store.Settings.DarkMode);dark.Checked+=(_,_)=>{var s=store.Settings;s.DarkMode=true;store.Settings=s;ApplyTheme(true);};dark.Unchecked+=(_,_)=>{var s=store.Settings;s.DarkMode=false;store.Settings=s;ApplyTheme(false);};p.Children.Add(Text("Original Heartbeat logo, Glow Outline navigation, Midnight Prism ribbon (72px), Mini Popover profile and Analog + Digital clock remain standard.",12));return Card(p,"Appearance customization");}
 private FrameworkElement DoctorsSettings(){var tabs=new TabControl();foreach(var group in new[]{"Referring","Performing"}){var p=Column();p.Children.Add(Text(group=="Referring"?"Referring Doctors (Kharian): centre-maintained directory":"Performing Doctors: manually added only; referring names never automatically appear here.",12));var name=Field(p,"Doctor name");var specialty=Field(p,"Specialty / hospital");p.Children.Add(Action("Add doctor",()=>{if(string.IsNullOrWhiteSpace(name.Text))return;var d=new Doctor{Name=name.Text.Trim(),Specialty=specialty.Text.Trim(),Group=group};store.Put("doctors",d.Id,d);OpenPage(page);},true));var records=store.All<Doctor>("doctors").Where(x=>x.Group==group).ToList();var grid=GridView(records,300);p.Children.Add(grid);p.Children.Add(Action("Remove selected doctor",()=>{if(grid.SelectedItem is Doctor d){store.Delete("doctors",d.Id);OpenPage(page);}}));tabs.Items.Add(new TabItem{Header=group+" Doctors",Content=new ScrollViewer{Content=Card(p)}});}return tabs;}
 private FrameworkElement PrintSettings(){var s=store.Settings;var p=Column();p.Children.Add(Text("Official preprinted A4 page reserves 6.5cm at the top and 5cm at the bottom. These areas stay empty unless an Admin unlocks adjustment.",12));var lockBox=Check(p,"Lock reserved margins",s.PrintMarginsLocked);var top=Field(p,"Header reserved (cm)",s.HeaderCm.ToString());var bottom=Field(p,"Footer reserved (cm)",s.FooterCm.ToString());top.IsEnabled=bottom.IsEnabled=!s.PrintMarginsLocked;lockBox.Checked+=(_,_)=>top.IsEnabled=bottom.IsEnabled=false;lockBox.Unchecked+=(_,_)=>top.IsEnabled=bottom.IsEnabled=true;
  p.Children.Add(Action("Save print margins",()=>{if(current?.Role!="Admin")return;decimal t=Dec(top.Text),b=Dec(bottom.Text);if(t<0||b<0||t+b>23){Info("Invalid margins for A4 page.");return;}var x=store.Settings;x.PrintMarginsLocked=lockBox.IsChecked==true;x.HeaderCm=t;x.FooterCm=b;store.Settings=x;Info("Print layout saved.");},true));return Card(p,"Letterhead-safe A4 printing");}
 private FrameworkElement BriefSettings(){var p=Column();var lines=store.Settings.CustomBriefLines.ToList();var grid=new ListBox{ItemsSource=lines,Height=215,Margin=new Thickness(0,12,0,12)};var input=Field(p,"New or edited message", "",200);p.Children.Add(grid);var buttons=Row();buttons.Children.Add(Action("Add line",()=>{if(string.IsNullOrWhiteSpace(input.Text))return;lines.Add(input.Text.Trim());grid.ItemsSource=null;grid.ItemsSource=lines;input.Clear();}));buttons.Children.Add(Action("Edit selected",()=>{if(grid.SelectedIndex<0)return;lines[grid.SelectedIndex]=input.Text.Trim();grid.ItemsSource=null;grid.ItemsSource=lines;}));buttons.Children.Add(Action("Delete selected",()=>{if(grid.SelectedIndex<0)return;lines.RemoveAt(grid.SelectedIndex);grid.ItemsSource=null;grid.ItemsSource=lines;}));p.Children.Add(buttons);var only=Check(p,"Show only my custom lines",store.Settings.CustomOnly);p.Children.Add(Action("Save Now Brief messages",()=>{var x=store.Settings;x.CustomBriefLines=lines;x.CustomOnly=only.IsChecked==true;store.Settings=x;ShowBrief();Info("Now Brief lines saved locally.");},true));return Card(p,"Now Brief editor");}
 private FrameworkElement DataSettings(){var p=Column();p.Children.Add(Text("Current database: "+store.FileName,11));p.Children.Add(Action("Backup native SQLite database",()=>{var file=new SaveFileDialog{FileName="MediLabX-Native-Backup-"+DateTime.Now.ToString("yyyyMMdd-HHmm")+".sqlite",Filter="SQLite database|*.sqlite"};if(file.ShowDialog()==true){store.Backup(file.FileName);Info("Encrypted Windows drive / external backup recommended. Backup saved.");}},true));p.Children.Add(Text("Legacy migration: export ahdc_software_v1 JSON from old MediLab, then select its file here. Current legacy application remains unchanged. Existing native records are never dropped.",12));p.Children.Add(Action("Import MediLab legacy JSON",()=>{if(current?.Role!="Admin")return;var file=new OpenFileDialog{Filter="JSON backups|*.json"};if(file.ShowDialog()!=true)return;try{var backup=System.IO.Path.Combine(Store.Root,"pre-import-"+DateTime.Now.ToString("yyyyMMddHHmmss")+".sqlite");store.Backup(backup);var results=new LegacyImporter(store).Import(file.FileName);Info($"Import complete. Patients: {results.patients}, expenses: {results.expenses}, reports: {results.reports}, referring doctors: {results.doctors}. Backup: {backup}");}catch(Exception e){Error(e);}},true));p.Children.Add(Text("Native WPF code updates need a compiled .NET release. HTML-only updates cannot replace C#/XAML logic; JSON can update data, messages and theme settings only.",12));p.Children.Add(Text("Release channel: Native WPF — kept separate from existing MediLab X Electron update.json.",11));return Card(p,"Data safety and software updates");}
 private FrameworkElement About(){var p=Column();p.Children.Add(Text("MediLab X",30,true));p.Children.Add(Text("Native Windows Rebuild • 0.2.0 Preview",15));p.Children.Add(Text("A project by Taha Waleed",12,true));p.Children.Add(Text("A separate C# WPF desktop foundation with fluent/macOS-inspired design, local SQLite storage, receipt handling, clinical reporting, reagent tracking and staff administration.",12));p.Children.Add(Text("Not a production replacement yet: validation of real printers, legacy data migration, update deployment and all remaining specialist workflows is required before installing at a live diagnostic centre.",12,true));return Card(p,"About MediLab X");}
}